<?php require "config/db.php"; $category=$_GET["category"] ?? ""; $q=trim($_GET["q"] ?? ""); $sql="SELECT * FROM foods WHERE is_available=1"; $params=[]; if($category!==""){ $sql.=" AND category=?"; $params[]=$category; } if($q!==""){ $sql.=" AND (name LIKE ? OR description LIKE ?)"; $params[]="%$q%"; $params[]="%$q%"; } $sql.=" ORDER BY category,name"; $st=$pdo->prepare($sql); $st->execute($params); $foods=$st->fetchAll(); ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Menu | Foody Spot</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include "includes/nav.php"; ?><main class="container page"><div class="page-head"><span class="eyebrow">MADE FRESH FOR YOU</span><h1>Our menu<span>.</span></h1><p>Pick a favourite. We'll take care of the rest.</p></div><form class="search-form" method="get"><input name="q" placeholder="Search your favourite food..." value="<?= h($q) ?>"><button class="btn" type="submit">Search</button></form><div class="food-grid"><?php foreach($foods as $food): ?><article class="food-card"><img src="<?= h($food["image_url"]) ?>" alt="<?= h($food["name"]) ?>" onerror="this.src='https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=700'"><div class="food-info"><span class="food-category"><?= h($food["category"]) ?></span><h3><?= h($food["name"]) ?></h3><p><?= h($food["description"]) ?></p><div class="food-bottom"><strong>₹<?= number_format($food["price"],2) ?></strong><form method="post" action="cart.php"><input type="hidden" name="food_id" value="<?= (int)$food["id"] ?>"><button class="add-btn" name="add" value="1">Add +</button></form></div></div></article><?php endforeach; ?></div><?php if(!$foods): ?><p class="empty">No dishes found. Try another search.</p><?php endif; ?></main><?php include "includes/footer.php"; ?></body></html>